import{glob,mkdir,rm}from"node:fs/promises";import{text}from"node:stream/consumers";const STALE_DIST_ARTIFACTS=[`HEAD`,`config`,`hooks`,`objects`,`refs`,`.claude`];async function ensureDir(dirPath){await mkdir(dirPath,{recursive:!0})}async function cleanDistArtifacts(workspaceRoot){let removals=[];for await(let finalDir of glob(`packages/*/*/dist/final`,{cwd:workspaceRoot}))for(let artifact of STALE_DIST_ARTIFACTS)removals.push(rm(`${workspaceRoot}/${finalDir}/${artifact}`,{recursive:!0,force:!0}));await Promise.all(removals)}async function removeMcpJson(workspaceRoot){await rm(`${workspaceRoot}/.mcp.json`,{force:!0})}async function sessionStartHousekeepingHandler(event){let workspaceRoot=event.cwd;await Promise.all([ensureDir(`/tmp/claude`),ensureDir(`/tmp/claude-1000`),cleanDistArtifacts(workspaceRoot),removeMcpJson(workspaceRoot)])}function sessionStartHousekeepingParser(raw){return JSON.parse(raw)}function sessionStartHousekeepingWriter(_output){return``}async function runHookPlugin({parser,handler,writer}){let output=await handler(parser(await text(process.stdin)));process.stdout.write(writer(output))}await runHookPlugin({parser:sessionStartHousekeepingParser,handler:sessionStartHousekeepingHandler,writer:sessionStartHousekeepingWriter});export{};